setup_files.main.tf:
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "dev_instance_type" {
  type    = string
  default = "t3.micro"

  validation {
    condition     = contains(["t3.micro", "t3.small", "t3.medium"], var.dev_instance_type)
    error_message = "dev_instance_type must be one of t3.micro, t3.small, t3.medium"
  }
}

variable "staging_instance_type" {
  type    = string
  default = "t3.small"

  validation {
    condition     = contains(["t3.micro", "t3.small", "t3.medium"], var.staging_instance_type)
    error_message = "staging_instance_type must be one of t3.micro, t3.small, t3.medium"
  }
}

variable "prod_instance_type" {
  type    = string
  default = "t3.medium"

  validation {
    condition     = contains(["t3.micro", "t3.small", "t3.medium"], var.prod_instance_type)
    error_message = "prod_instance_type must be one of t3.micro, t3.small, t3.medium"
  }
}

reference_solution.main.tf:
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "instance_types" {
  type = map(string)
  default = {
    dev     = "t3.micro"
    staging = "t3.small"
    prod    = "t3.medium"
  }

  validation {
    condition     = alltrue([for v in values(var.instance_types) : contains(["t3.micro", "t3.small", "t3.medium"], v)])
    error_message = "every instance type must be one of t3.micro, t3.small, t3.medium"
  }
}

